@1812:
	SetMapTrap(1,"trap01.txt");
	Say("纳兰真：影枫哥，眉儿姐好了吗？",9);
	Say("杨影枫：她没事了，不过还没有醒。",2);
	Say("纳兰真：我们一起去看看她吧。",9);
	Say("杨影枫：好。",2);
	FadeOut();
	DelObj("躺着的月眉儿");
	DelNpc("月眉儿");
	AddNpc("月眉儿.ini",24,99,7);
	SetNpcPos("蔷薇",25,100);
	SetNpcDir("蔷薇",3);
	SetNpcKind("纳兰真",3);
	SetPlayerDir(5);
	SetPlayerPos(24,104);
	FadeIn();
	Watch("杨影枫","蔷薇",0);
	Say("杨影枫：蔷薇，你也来了。",3);
	Say("蔷薇：杨大哥，月姑娘已经醒了。",30);
	PlayerGoto(24,101);
	Watch("杨影枫","月眉儿",0);
	NpcGoto("纳兰真",24,102);
	Say("杨影枫：……",2);
	Say("纳兰真：眉儿姐，你还好吧。",9);
	Say("月眉儿：杨影枫，你为什么不杀了我？",24);
	Say("杨影枫：月眉儿，对不起，以前是我误会了你……",2);
	Say("月眉儿：哼！不要以为你救了我，我就会领你的情。",24);
	Say("蔷薇：月姑娘，你怎么这么说话呢？我爹为了救你可是消耗了不少的元气呢。",31);
	Say("纳兰真：眉儿姐……你就原谅了杨大哥吧。",12);
	NpcSpecialAction("月眉儿","mpc160.asf");
	Sleep(4000);
	FadeOut();
	Say("……良久……");
	Say("纳兰真：眉儿姐，我们一起去忘忧岛吧，只有那儿的银丝草才能把你的伤彻底治好。",9);
	SetNpcKind("纳兰真",1);
	SetNpcKind("月眉儿",1);
	SetNpcPos("蔷薇",6,127);
	SetNpcDir("蔷薇",1);
	SetNpcPos("纳兰真",5,128);
	SetNpcDir("纳兰真",5);
	SetNpcPos("月眉儿",6,130);
	SetNpcDir("月眉儿",5);
	SetPlayerPos(5,129);
	SetPlayerDir(5);
	FadeIn();
	Say("杨影枫：蔷薇，快回去吧。",2);
	Say("蔷薇：杨大哥，真儿姐，记得来看我。",32);
	Say("纳兰真：薇儿妹妹，我们会来看你的。",9);
	Say("蔷薇：杨大哥，真儿姐，再见。",32);
	SetNpcKind("纳兰真",3);
	SetNpcKind("月眉儿",3);
	PlayerGotoEx(2,139);
	Sleep(1000);
	StopMusic();
	FadeOut();

	SetNpcPos("蔷薇",24,18);
	SetNpcPos("孟知秋",18,93);
	SaveNpc();
	SaveObj();

	Say("经过数日行程，三人终于又回到了忘忧岛");
	LoadMap("map_051_海边.map");
	LoadNpc("map051.npc");
	LoadObj("map051_obj.obj");
	AddObj("躺着的眉儿.ini",11,33,0);
	SetObjOfs("躺着的眉儿",0,15);
	SetNpcKind("月眉儿",1);
	SetNpcKind("纳兰真",1);
	DelNpc("月眉儿");
	SetPlayerPos(12,39);
	SetPlayerDir(3);

	SetNpcPos("纳兰真",12,38);
	SetNpcDir("纳兰真",7);
	SaveNpc();
	SaveObj();
	FadeIn();
	PlayMusic("mc004.mp3");
	Say("纳兰真：影枫哥，你去离忧山采草药吧，我在这里照顾眉儿姐。",9);
	Say("杨影枫：好吧，我会很快回来的。",2);
	Assign($Event,1813);
	SetNpcDir("纳兰真",3);
	Memo("采十二株银丝草");
	Return;

@1811:
	Say("纳兰真：影枫哥，你起来了，看过眉儿姐了吗？",9);
	Say("杨影枫：还没有。",2);
	Say("纳兰真：你先去吧，我要梳妆一下再过去。",9);
	Return;

@1810:
	Say("杨影枫：真儿，还没睡。",3);
	Say("纳兰真：影枫哥，其实蔷薇妹妹人也满好的……",12);
	Say("杨影枫：真儿，我只喜欢你。",3);
	Say("纳兰真：影枫哥，等月姑娘的伤势好一点了，我们就回忘忧岛吧……",9);
	Say("杨影枫：嗯……真儿，你早点休息吧。",2);
	Say("纳兰真：影枫哥……你也早点睡吧。",9);
	Return;
	
@1809:
	Say("杨影枫：真儿！",3);
	Say("纳兰真：影枫哥！",9);
	PlayerGoto(25,100);
	SetPlayerDir(3);
	SetNpcKind("蔷薇",1);
	NpcGoto("蔷薇",24,101);
	SetNpcDir("蔷薇",4);
	SetNpcDir("纳兰真",0);
	Say("杨影枫：真儿，这位就是孟府的千金—蔷薇小姐。",3);
	Say("纳兰真：真儿见过蔷薇小姐。",9);
	Say("蔷薇：原来你就是杨大哥常提起的纳兰姑娘呀，难怪你失踪后杨大哥急成那个样子。",30);
	Say("纳兰真：（脸红）蔷薇小姐见笑了",121);
	Say("蔷薇：别老是小姐、小姐的，叫我薇儿好了，真儿姑娘你今年多大了？",30);
	Say("纳兰真：我今年一十九了。",10);
	Say("蔷薇：我小你一岁，该叫你一声真儿姐了。",30);
	Say("纳兰真：薇儿妹妹。",10);
	Say("杨影枫：真儿，孟前辈已经同意救月眉儿了！",3);
	Say("纳兰真：真的吗？太好了。",9);
	Say("杨影枫：这还要多亏蔷薇了……",3);
	Say("纳兰真：真儿替月姑娘多谢蔷薇妹妹了",10);
	Say("蔷薇：不用谢，杨大哥也曾救过我一命呢。",30);
	Say("纳兰真：薇儿妹妹，你不但人长得漂亮，心也这么好，真是难得。",9);
	Say("蔷薇：我哪儿有真儿姐姐长得这么漂亮呀？",30);
	Say("纳兰真：（害羞）……",121);
	Say("蔷薇：走吧，我带你们去住的地方。",30);
	FadeOut();
	Say("当晚");
	SetNpcKind("蔷薇",1);
	SetNpcPos("蔷薇",24,18);
	SetNpcDir("蔷薇",5);
	SetNpcPos("纳兰真",41,115);
	SetNpcDir("纳兰真",5);
	SetNpcPos("孟知秋",24,99);
	SetNpcDir("孟知秋",5);
	SetPlayerPos(44,98);
	SetPlayerDir(1);
	ChangeMapColor(125, 150, 255);
	ChangeAsfColor(150, 200, 255);
	FadeIn();
	Assign($Event, 1810);
	Return;

@1806:
	Say("杨影枫：真儿，到底发生了什么事，快告诉我好吗？",2);
	Say("纳兰真：影枫哥，那天晚上，我独自出去散步，谁知遇到了十几个蒙面人围攻，他们个个身手不俗，我被点了穴道昏倒在地……",12);
	Say("杨影枫：那后来呢？",4);
	Say("纳兰真：后来在他们押送我的途中遇到了月姑娘，才知道原来那些蒙面人在假扮飞龙堡的弟子，多亏月姑娘把他们杀退才把我救了出来……",12);
	Say("杨影枫：原来是这样……看来绑架蔷薇也是另有其人了。",7);
	Say("纳兰真：后来月姑娘回飞龙堡途中遇到了飞龙堡的总管卢肇颢，得知你大闹飞龙堡，打死打伤无数飞龙堡弟子，月姑娘非常生气……",12);
	Say("杨影枫：唉……都怪我救人心切……错怪了月眉儿……",7);
	Say("纳兰真：孟前辈……他是否肯为月姑娘疗伤呢？",9);
	Say("杨影枫：……他有一个条件……",7);
	Say("纳兰真：什么条件？",9);
	Say("杨影枫：……他……要我娶蔷薇为妻……",5);
	Say("纳兰真：（吃惊）啊……",12);
	Say("杨影枫：可是……我真正喜欢的是你……真儿",7);
	Say("纳兰真：影枫哥，我知道……但是眉儿姐她……太可怜了。",12);
	Say("杨影枫：你等着我，我去找蔷薇。",2);
	Say("纳兰真：嗯……影枫哥。",12);
	Assign($Event, 1807);
	Memo("去找蔷薇想想办法");
	Return;

@1807:
	Say("杨影枫：我会想办法让孟盟主救月眉儿的。",2);
	Say("纳兰真：嗯……",12);
	Return;

@1808:
	Say("杨影枫：我要去找蔷薇姑娘，你先在这里等我好吗？",2);
	Say("纳兰真：好的……",12);
	Return;

scripts.蔷薇对话.txt:
	If ($Event == 1819) @1819;//结局2求证
	If ($Event == 1812) @1812;//结局2救月眉儿
	If ($Event == 1811) @1811;//结局2救月眉儿
	If ($Event == 1810) @1810;//结局2救月眉儿
	If ($Event == 1809) @1809;//结局2救月眉儿
	If ($Event == 1805) @1805;//结局2送蔷薇回来
	If ($Result == 3) @Result3;	
	If ($Event == 550) @Label;
	If ($Event == 555) @Label3;
	If ($Event == 560) @Label1;
	If ($Event == 562) @Label2;
	If ($Event == 574) @TalkE574;
	Return;
	
@1819:
	Say("蔷薇：影枫哥，我爹是冤枉的。",29);
	Say("杨影枫：问过天星道长就知道了。",2);
	Say("蔷薇：影枫哥，难道你还不相信我？",29);
	Say("杨影枫：不是，只是……",2);
	Return;

@1812:
	Say("蔷薇：杨大哥，月姑娘怎么样了？",29);
	Say("杨影枫：她没事了，多亏了你爹。",3);
	Say("蔷薇：杨大哥，你还是看看真儿姐吧，要不她该吃我的醋了。",29);
	Return;

@1811:
	Say("蔷薇：杨大哥，这么早，快去看看月姑娘吧，我梳妆一下再去。",29);
	Return;
	
@1810:
	StopMusic();
	PlayMusic("mc006.mp3");
	Say("蔷薇：杨大哥，找我有事吗？",29);
	Say("杨影枫：蔷薇……白天的事多亏你了",3);
	Say("蔷薇：没什么，本来就是我爹的不对嘛",29);
	Say("杨影枫：蔷薇……你真是太好了",3);
	Say("蔷薇：杨大哥，我有个东西送给你……",29);
	Say("说着蔷薇摘下了自己的发钗");
	Say("蔷薇：杨大哥，那次都是我太任性了……你还怪我吗？",29);
	Say("杨影枫：不怪（才怪，我差点就成了杀人鱼的美餐）",3);
	Say("蔷薇：那这只发钗你就收下，你冒了那么大的危险才把它捡回来，留个纪念吧。",29);
	Say("杨影枫：好吧（我要发钗有什么用？）",7);
	AddGoods("Goods-e09-发钗.ini");
	Sleep(1000);
	Say("蔷薇：杨大哥，我睡不着，你陪我出去散散步好吗？",29);
	Say("杨影枫：好吧……",3);
	FadeOut();
	SetNpcPos("蔷薇",5,55);
	SetNpcDir("蔷薇",7);
	SetPlayerPos(5,56);
	SetPlayerDir(7);
	FadeIn();
	Say("蔷薇：等月眉儿的伤好了，你是不是就要回去了。",29);
	Say("杨影枫：是的……我要带她去忘忧岛，只有那儿的草药才能让她彻底痊愈。",2);
	Say("蔷薇：真儿姐也跟你们一起走吗？",29);
	Say("杨影枫：嗯……她的家就在那里。",2);
	Say("蔷薇：我能跟你们一起走吗？",29);
	Say("杨影枫：这……你爹恐怕不会同意的。",7);
	Say("蔷薇：只要你答应，我爹不会不同意的。",29);
	Say("杨影枫：但是……这恐怕不大好吧……",7);
	Say("蔷薇：……",32);
	Say("杨影枫：蔷薇……等月眉儿伤好了我会来看你的。",3);
	Say("蔷薇：真的吗？",29);
	Say("杨影枫：一定。",3);
	Say("蔷薇：那我等你。",29);
	Say("杨影枫：（后悔）哦……",2);
	StopMusic();
	FadeOut();
	Say("第二天");
	SetNpcPos("蔷薇",24,18);
	SetNpcDir("蔷薇",7);
	SetPlayerPos(46,106);
	SetPlayerDir(1);
	SetNpcPos("孟知秋",0,0);
	SetNpcDir("孟知秋",5);
	SetNpcPos("侍女樱儿",25,99);
	SetNpcDir("侍女樱儿",1);
	ChangeMapColor(255, 255, 255);
	ChangeAsfColor(255, 255, 255);
	FadeIn();
	PlayMusic("mc007.mp3");
	Say("杨影枫：不知道月眉儿的伤势怎么样了，我赶紧去看一看吧。",2);
	Assign($Event,1811);
	Return;

@1809:
	Say("杨影枫：谢谢你……蔷薇。",3);
	Say("蔷薇：别这么客气……杨大哥。",29);
	Return;

@1805:
	If ($qiangwei == 9) @1805a;
	Say("蔷薇：杨大哥，你能留下来陪陪我吗？",29);
	Say("杨影枫：我还要去救真儿，不能在这里久留。",2);
	Say("蔷薇：杨大哥，那我跟你一起去好吗？",29);
	Say("杨影枫：别瞎闹了，你爹不会同意的。",2);
	Say("蔷薇：杨大哥，我有一件东西送给你。",29);
	Say("说着蔷薇从身上取下一串精美的挂链");
	Say("杨影枫：这么珍贵的东西，你还是自己留着吧。",3);
	Say("蔷薇：杨大哥，你是不是嫌弃我呀？",31);
	Say("杨影枫：不……怎么会？好吧……我收下就是。",3);
	Say("蔷薇：杨大哥，你还会来看我吗？",29);
	Say("杨影枫：我会的。",2);
	Say("蔷薇：杨大哥，我等你。",29);
	AddGoods("goods-n10-碧玉挂链.ini");
	Assign($qiangwei,9);
	Return;

@1805a:
	Say("蔷薇：杨大哥，记得来看我哦。",29);
	Say("杨影枫：我会的。",2);
	Return;

@Label:
	If ($QiangWeiSense >= 20) @AddSenseEnd;
		Add($SenseVal, 5);
		Add($QiangWeiSense, 5);
	@AddSenseEnd:
	Say("蔷薇：我已经有整整一周没有见到我爹了！", 29);
	Say("杨影枫：你爹平时很少在家吗？", 2);
	Say("蔷薇：嗯，即使在家，也总是闭关练功，从来不陪我玩！", 29);
	Say("杨影枫：其他人呢？", 2);
	Say("蔷薇：他们看见我要么就点头哈腰，要么就逃之夭夭，一点都不好玩！", 29);
	Say("杨影枫：（蔷薇和真儿的爹都是武林中的一流高手，可他们都为了自己的地位，冷落了身边最亲的人…）", 2);
	Return;

@Label3:
	Say("杨影枫：你爹正在大厅等你呢，我们现在就去见你爹吧！", 2);
	Say("蔷薇：（我才不要见我爹呢！）", 29);
	Return;

@Label1:
	SetPlayerDir(1);
	Talk(10860, 10891);
	NpcGoto("蔷薇", 7,122);
	SetNpcDir("蔷薇", 7);
	PlayerGoto(6, 128);
	SetPlayerDir(1);
	Talk(10900, 10900);
	SetNpcDir("蔷薇", 1);
	Assign($Event, 562);
	SetMapTrap(1, "trap01.txt");
	Return;
	
@Label2:
	Talk(10901, 10901);
	Return;
	
@TalkE574:
	Talk(60190,60250);
	Return;
	
@Result3:
	If ($Event <= 870) @EventL870;
	GetRandNum($GanTalk, 5, 6);
	If ($GanTalk == 5) @GanTalk35;
	If ($GanTalk == 6) @GanTalk36;
@GanTalk35:
	Say("蔷薇：……", 32);
	Say("杨影枫：……", 7);
	Return;
@GanTalk36:
	Say("蔷薇：那位姐姐你找到了吗？", 32);
	Say("杨影枫：惭愧，还没找到。", 2);
	Return;
@EventL870:
	GetRandNum($GanTalk, 1, 2);
	If ($GanTalk == 1) @GanTalk31;
	If ($GanTalk == 2) @GanTalk32;
@GanTalk31:
	Say("蔷薇：你来了，我好久没看到你了。", 32);
	Return;
@GanTalk32:
	Say("蔷薇：带我出去玩好吗，我在谷里好闷啊，你的悲魔山庄好玩吗？", 32);
	Say("杨影枫：……我有些琐事缠身，下次吧。", 2);
	Return;

@end:
	Return;

